mapper.select:
SELECT id
FROM recommendation
WHERE couple_id = #{coupleId}

SELECT r.id
FROM recommendation r
    INNER JOIN couple c
        ON c.id = r.couple_id
WHERE c.inviter_id = #{memberId}
   OR c.invitee_id = #{memberId}

