mapper.select:
SELECT COUNT(*)
FROM recommendation
WHERE couple_id = #{coupleId}

SELECT COUNT(*)
FROM recommendation_slot
WHERE recommendation_id = #{recommendationId}

SELECT COUNT(*)
FROM recommendation_slot
WHERE recommendation_id = #{recommendationId}
  AND slot_type = #{slotType}

SELECT COUNT(*)
FROM personal_recommendation_tax_saving
WHERE member_id = #{memberId}

